# reload = "all"; a C host calls `on_audio` from its audio thread whenever it likes
@unsafe(export("on_audio", threads=any))
fn on_audio():
    mix(GAME)                    # entering: "one relaxed increment and one acquire fence"; nothing waits

fn main():
    while running:
        tick()
        std.hot.checkpoint()     # <-- commit reads the audio thread's counter (0: it is in C), then stores the new call table and instances one pointer at a time; the audio thread enters between that read and the generation store and runs new `mix` over unpublished instances, or old code over published ones

struct Mesh:
    x: f64
    y: f64
class Body:
    let mesh: owns Mesh
    tip: ref f64 from mesh               # a kept view into `mesh.x` ([TYP-15])
    fn init(this):
        this.tip = ref this.mesh.x

fn main():
    b = Body(mesh=owns Mesh(x=1.0, y=2.0))
    while running:
        println(b.tip)                    # <-- after a reload that adds `w: f64 = 0.0` before `x`: the `mesh` block grows and moves, commit rewrites `tip` to the new block at the old offset, and it reads `w`; after one that removes `x`: `tip` points at memory reclaim ends
        std.hot.checkpoint()

struct Vec2:
    x: f64
    y: f64
class Bus:
    handlers: Array[fn(f64)]

fn main():
    bus = Bus(handlers=[])
    v = Vec2(x=1.0, y=2.0)
    bus.handlers.push(owns fn(t: f64) copy of v: println(v.x * t))   # the lambda's state block holds a 16-byte Vec2 ([CLO-10])
    while running:
        for h in bus.handlers:
            h(0.5)                   # <-- after a reload that adds `z: f64 = 0.0` to Vec2 and `v.z` to the body: the thunk runs the new body, which reads 8 bytes past the state block
        std.hot.checkpoint()

class Tree:
    nodes: Array[owns Node]
    on_visit: fn(Node)
    fn setup(this):
        this.on_visit = prune            # old image: `prune` reaches `on_visit`, so the old `walk` had to walk with a `weakref` link ([WK-18])
    fn walk(this):
        for n in this.nodes:
            this.on_visit(n)             # <-- new image: `setup` now stores `log_visit`, which ends nothing, so this `walk` with plain views is accepted when it compiles; the live `tree.on_visit` still holds `prune`, which ends `n` under the view
fn prune(n: Node): ...                   # removes nodes through a `shares mut` link to the tree

fn fresh_id() -> int:
    return NEXT.fetch_add(1).unwrap_overflow()     # or any body with a bounds check, overflow or `unwrap`
class Player:
    hp: int
    id: int = fresh_id()        # <-- the edit adds this field; [HR-14]: "field added with a default | initialised to that default": prepare runs `fresh_id()` once per instance ([STR-2]: "evaluated at each construction"), compiled as any function: its panic aborts the process, which [HR-34] forbids

class Audit:
    static fn migrate_from(old: OldSelf) -> Result[Self, ReloadError]:
        return Ok(Audit(total=sum_all(old.parts)))   # <-- `sum_all` is an ordinary function: its overflow check panics; [HR-35] rewrites only checks "inside it"

@inline
fn depth(n: Node) -> int:
    if n.next exists as m:
        return 1 + depth(m)       # <-- `__attribute__((always_inline))` on a recursive function: GCC and Clang warn ("inlining failed"), which [CG-C-2] forbids an accepted program to produce
    return 1

# C host: pthread_attr_setstack(&attr, buf, 64 * 1024) with no guard region, then calls the exported `on_audio`
@unsafe(export("on_audio", threads=any))
fn on_audio():
    deep(100000)               # <-- [RT-12]: "A stack write can never land beyond the guard page" — this thread has none: the probes walk into whatever lies below `buf`

fn render(device: dyn Device):
    if device.begin_frame() exists as frame:
        if skip: return              # <-- `frame` ends here without `end_frame`: nothing says what the device sees (a frame never submitted? a fence never signalled, so the next `begin_frame` waits for ever?)
        staging = Array.new_in(frame.arena())   # a value made `using` the frame's arena: if the device uploads from it, the GPU reads it after `end_frame` reset the arena
